public static class Experiments150{
 public static void Critical(bool feedback=false,string? label=null){var mode=label??(feedback?"tube":"fixed");using var budget=new Budget150("prototype-critical-1s-"+mode,0,160);var summary=new List<object>();foreach(var model in new[]{false,true}){
  var key=model?"B":"A";var tape=Program150.Read<Tape150>(Program150.Doc+"/diagnosis-safe/"+key+"-A-original-fixed.json.gz");var old=Program150.Read<Run144>(Diagnosis150.Previous+"/fixtures/planned-entry-90-outer-"+key+".json.gz");var sample=old.Riders[0].Samples[^1];var planner=new Planner150(old.Riders[0].Spec,model,new(Enabled:true,Laps:1,Feedback:feedback),budget.Guard);planner.InitializeDiagnosticTape(tape);string? failure=null;
  try{planner.Choose(sample.Input,new(omega:sample.CrankOmega));}catch(InvalidOperationException error){failure=error.Message;}
  Program150.Save("prototype-critical-"+mode+"-"+key+".json",new{Failure=failure,Review=planner.Last,Scope="Detached accepted1s observation; own old complete plan supplied as diagnostic incumbent, never as a scripted native improvement."});summary.Add(new{Model=key,Failure=failure,Reason=planner.Last?.Reason,Legal=planner.Last?.Legal,Robust=planner.Last?.Robust,Counts=planner.Runtime.Counters()});Console.WriteLine(key+": "+(failure??"certified new continuation"));
 }Program150.Save("prototype-critical-"+mode+"-summary.json",summary);budget.Finish("critical pair complete; see explicit abstentions");}
 public static void Native(string name,bool model,bool rolling=false,bool feedback=false,double? prefixUntil=null,bool criticalPrefix=false,bool spatial=false,bool accepted=false,bool joint=false){using var budget=new Budget150(name,1,240);var process=Process.GetCurrentProcess();if(criticalPrefix)prefixUntil=1;var records=criticalPrefix?Journal147.ReadComplete(Diagnosis150.Previous+"/fixtures/planned-entry-90-outer-"+(model?"B":"A")+"-decisions.jsonl").Where(x=>x.GetProperty("Event").GetString()=="decision").ToArray():prefixUntil is not null?StateProbes150.Journal(model):null;bool prefixExact=true;Planner150? planner=null;using var journal=new Journal147(Program150.Doc+"/native/"+name+"-decisions.jsonl");var spec=rolling?StandingWorld144.Rider(CoreSim.StartingGate.B) with{SpeedMetersPerSecond=90/3.6f,ReferenceMeters=23,OffsetMeters=10}:null;double attempted=0;var costs=new List<double>();var anchors=new Dictionary<Tape150,string>(ReferenceEqualityComparer.Instance);string? lastAnchor=null;FreeRacingAction? expected=null;
  Decision144 Choose(FreeRacingInput i,CrankClutch144 c,RiderSpec s,TrackFrame f,CoreSim.TrackStateSnapshot surface,WorldParameters p,float mass,float inertia,string variant){var entered=process.TotalProcessorTime;budget.Guard();if(prefixUntil is double cut&&i.Time<cut-1e-7){var row=records!.Single(x=>Math.Abs(x.GetProperty("Time").GetDouble()-i.Time)<1e-7);var old=StateProbes150.State(row);prefixExact&=ExactKey147.State(new(i,c.Omega))==ExactKey147.State(old);if(!prefixExact)throw new InvalidOperationException("diagnostic prefix differs");return new(new(i.Time,row.GetProperty("Selected").Deserialize<FreeRacingAction>(Program150.Json),FreeActionSafety.Uncertain,false,Array.Empty<FreeLearningCandidate>(),0,0),0);}if(planner is null){planner=new(s,model,new(Enabled:true,Laps:rolling?1:3,Feedback:feedback,SpatialFeedback:spatial,AcceptedOperatingPoint:accepted,JointFeedback:joint),budget.Guard);if(criticalPrefix)planner.InitializeDiagnosticTape(Program150.Read<Tape150>(Program150.Doc+"/diagnosis-safe/"+(model?"B":"A")+"-A-original-fixed.json.gz"));}try{var decision=planner.Choose(i,c);var anchor=planner.SelectedAnchor!;if(!anchors.TryGetValue(anchor,out var id)){id="anchor-"+(anchors.Count+1).ToString("D4");anchors[anchor]=id;Program150.Save("plans/"+name+"/"+id+".json.gz",anchor);}journal.Append(new{Event="decision",i.Time,Selected=decision.Choice.Action,Anchor=id,ExpectedAction=expected,SameFeedbackContract=lastAnchor==id,Cause=lastAnchor==id?"same causal feedback contract re-evaluated":"new independently certified maneuver",Review=planner.Last});lastAnchor=id;expected=planner.Last!.Selected!.Length>1?planner.Last.Selected[1]:null;return decision;}catch(InvalidOperationException error){journal.Append(new{Event="abstain",i.Time,Reason=error.Message,Observed=i,Review=planner.Last,Counts=planner.Runtime.Counters()});throw;}finally{var cost=(process.TotalProcessorTime-entered).TotalSeconds;attempted+=cost;costs.Add(cost);}}
  Run144 run;using(var w=new DiagnosticWorld149(new(Enabled:true,RequiredLaps:rolling?1:3,MaximumSeconds:rolling?18:120),diagnosticRider:spec,separated:model))run=w.Run(name,"K1",Choose);journal.Append(new{Event="summary",run.Outcome,run.Fingerprint});Program150.Save("native/"+name+".json.gz",run);var ss=run.Riders[0].Samples;double? Percentile(double f)=>costs.Count==0?null:costs.Order().ElementAt((int)((costs.Count-1)*f));
  Program150.Save("native/"+name+"-result.json",new{Model=model?"B":"A",RollingDiagnostic=rolling,DiagnosticPrefixUntil=prefixUntil,PrefixExact=prefixExact,Options=planner?.Options,InverseQuerySeconds=planner?.Runtime.InverseStepSeconds,SourceHashes=Program150.SourceHashes(),run.Outcome,run.EndSeconds,run.Fingerprint,FinishSeconds=run.Riders[0].FinishSeconds,Laps=run.Riders[0].CompletedLaps,ControllerAttemptCpu=attempted,ControllerCpuReturnedDecisionsOnly=run.ControllerCpuSeconds,DecisionCpuMedian=Percentile(.5),DecisionCpuP95=Percentile(.95),DecisionCpuMaximum=costs.Count>0?(double?)costs.Max():null,MinimumGap=ss.Min(s=>Math.Min(s.Inner,s.Outer)),MinimumSweep=ss.Where(s=>s.Certificate is not null).Min(s=>s.Certificate),MaximumBeta=ss.Max(s=>Math.Abs(s.Input.Rider.SlideRadians)*180/Math.PI),Contacts=run.Contacts.Length,CpuSeconds=budget.Elapsed,Counts=planner?.Runtime.Counters(),Scope=prefixUntil is null?"All choices generated by planner150; same native A/B world, no forced controls or native state restoration.":"Full native prefix from0 using saved own-model controls, then planner150. Diagnostic only, not full autonomous improvement."});budget.Finish(run.Outcome);Console.WriteLine(name+": "+run.Outcome+" time="+run.EndSeconds+" CPU="+budget.Elapsed);
 }
}
